const getOperatingUnitHierarchy = `-- name: GetOperatingUnitHierarchy :many
WITH RECURSIVE tree AS (
    SELECT ou.id, ou.public_id, ou.code, ou.name, ou.unit_type, ou.status,
           ou.parent_unit_id, ou.pincode, ou.city_id, 0 AS depth,
           ARRAY[ou.code]::text[] AS path
    FROM operating_units ou
    WHERE ou.organization_id = $1
      AND (CASE WHEN $2::text IS NULL
                THEN ou.parent_unit_id IS NULL
                ELSE ou.public_id = $2 END)
    UNION ALL
    SELECT c.id, c.public_id, c.code, c.name, c.unit_type, c.status,
           c.parent_unit_id, c.pincode, c.city_id, t.depth + 1,
           t.path || c.code
    FROM operating_units c
    JOIN tree t ON c.parent_unit_id = t.id
    WHERE t.depth < $3::int
      AND c.organization_id = $1
      AND NOT c.code = ANY(t.path)
)
SELECT id, public_id, code, name, unit_type, status, parent_unit_id, pincode, city_id, depth, path FROM tree ORDER BY path
`

type GetOperatingUnitHierarchyParams struct {
	OrganizationID int64
	RootPublicID   *string
	MaxDepth       int32
}

type GetOperatingUnitHierarchyRow struct {
	ID           int64
	PublicID     string
	Code         string
	Name         string
	UnitType     string
	Status       string
	ParentUnitID *int64
	Pincode      string
	CityID       *int64
	Depth        int32
	Path         []string
}

// GetOperatingUnitHierarchy walks down from a root unit.
//
// The recursive CTE is depth-limited so a cycle introduced by bad data cannot
// spin forever; the not-self-parent CHECK prevents the trivial case and this
// bound covers the rest.
func (q *Queries) GetOperatingUnitHierarchy(ctx context.Context, arg GetOperatingUnitHierarchyParams) ([]GetOperatingUnitHierarchyRow, error) {
	rows, err := q.db.Query(ctx, getOperatingUnitHierarchy, arg.OrganizationID, arg.RootPublicID, arg.MaxDepth)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []GetOperatingUnitHierarchyRow{}
	for rows.Next() {
		var i GetOperatingUnitHierarchyRow
		if err := rows.Scan(
			&i.ID,
			&i.PublicID,
			&i.Code,
			&i.Name,
			&i.UnitType,
			&i.Status,
			&i.ParentUnitID,
			&i.Pincode,
			&i.CityID,
			&i.Depth,
			&i.Path,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

