const resolveAncestorHub = `-- name: ResolveAncestorHub :one
WITH RECURSIVE up AS (
    SELECT ou.id, ou.public_id, ou.code, ou.name, ou.unit_type, ou.parent_unit_id, ou.status, 0 AS depth
    FROM operating_units ou
    WHERE ou.id = $1 AND ou.organization_id = $2
    UNION ALL
    SELECT p.id, p.public_id, p.code, p.name, p.unit_type, p.parent_unit_id, p.status, u.depth + 1
    FROM operating_units p
    JOIN up u ON p.id = u.parent_unit_id
    WHERE u.depth < 10
)
SELECT id, public_id, code, name, unit_type, status, depth FROM up
WHERE unit_type IN ('DELIVERY_HUB','TRANSIT_HUB','REGIONAL_HUB')
ORDER BY depth
LIMIT 1
`

type ResolveAncestorHubParams struct {
	UnitID         int64
	OrganizationID int64
}

type ResolveAncestorHubRow struct {
	ID       int64
	PublicID string
	Code     string
	Name     string
	UnitType string
	Status   string
	Depth    int32
}

// ResolveAncestorHub walks up from a branch to the nearest hub.
//
// Routing is defined between hubs, so every branch must resolve to one; the
// walk stops at the first ancestor whose unit_type is a hub type.
func (q *Queries) ResolveAncestorHub(ctx context.Context, arg ResolveAncestorHubParams) (ResolveAncestorHubRow, error) {
	row := q.db.QueryRow(ctx, resolveAncestorHub, arg.UnitID, arg.OrganizationID)
	var i ResolveAncestorHubRow
	err := row.Scan(
		&i.ID,
		&i.PublicID,
		&i.Code,
		&i.Name,
		&i.UnitType,
		&i.Status,
		&i.Depth,
	)
	return i, err
}

